function ActionForm({title,button,notice,onSubmit}:{title:string;button:string;notice:string;onSubmit:()=>Promise<unknown>}) {
 const [busy,setBusy]=useState(false);const [error,setError]=useState("");
 return <form className="form-stack" onSubmit={async event=>{event.preventDefault();setBusy(true);setError("");try{await onSubmit();}catch(cause){setError(cause instanceof Error?cause.message:"Operation failed.");}finally{setBusy(false);}}}><h2>{title}</h2><p>{notice}</p><label className="check-label"><input type="checkbox" required/><span>I have reviewed this action and its current records.</span></label>{error&&<p className="admin-error" role="alert">{error}</p>}<button className="button button-secondary" disabled={busy}>{busy?"Saving…":button}</button></form>;
}
function UploadForm({galleryId,onComplete}:{galleryId:string;onComplete:()=>void}) {
 const [busy,setBusy]=useState(false);const [error,setError]=useState("");
 return <form className="form-stack" onSubmit={async event=>{event.preventDefault();setBusy(true);setError("");const file=new FormData(event.currentTarget).get("file") as File;try{const bytes=await file.arrayBuffer();const hash=[...new Uint8Array(await crypto.subtle.digest("SHA-256",bytes))].map(byte=>byte.toString(16).padStart(2,"0")).join("");const intent=await api<{assetId:string;uploadUrl:string}>("/admin/media/upload-intents",{galleryId,mimeType:file.type,sizeBytes:file.size,checksumSha256:hash},undefined,crypto.randomUUID());const response=await fetch(intent.uploadUrl,{method:"PUT",headers:{"Content-Type":file.type},body:bytes,credentials:"same-origin"});if(!response.ok)throw new Error("The upload was rejected. Check file type, size and content.");await api(`/admin/media/${intent.assetId}/complete`,{},undefined,crypto.randomUUID());onComplete();}catch(cause){setError(cause instanceof Error?cause.message:"Upload failed.");}finally{setBusy(false);}}}><h2>Upload to quarantine</h2><label>Photo or video<input type="file" name="file" accept="image/jpeg,image/png,image/webp,video/mp4" required/></label><p className="small">Private originals are never published automatically. The server checks bytes, checksum, assignment and processing state.</p>{error&&<p className="admin-error" role="alert">{error}</p>}<button className="button button-secondary" disabled={busy}>{busy?"Uploading…":"Upload for processing"}</button></form>;
}
